import * as T from './three.module.js';
import {hull,meshOutline,overlaps} from './screen-hit.mjs?v=bodyhit11';
import {createWizard,animateWizard,projectWizard} from './wizard.mjs?v=hand-clips-1';
// Headless server fallback. The live game and preview supply their rendered camera.
export let combatCamera=new T.OrthographicCamera(-30,30,30,-30,.01,1000);combatCamera.position.set(120,170,150);combatCamera.lookAt(0,0,0);combatCamera.updateMatrixWorld(true);
export function setCombatCamera(camera){combatCamera=camera;}
const rigs=new WeakMap();
export function actorShapes(actor,camera=combatCamera){if(actor.monster&&actor.body){actor.g.position.set(actor.x,0,actor.z);return [meshOutline(actor.body,camera)];}let g=actor.g;if(!g?.userData.puppet){let rig=rigs.get(actor);if(!rig){rig=createWizard(new T.Group(),0,0);rigs.set(actor,rig);}g=rig;g.position.set(actor.x,0,actor.z);g.rotation.y=Math.atan2(actor.dir?.x||0,actor.dir?.z??1);animateWizard(g,0,{charging:actor.charge?.active||false});g.userData.puppet.icePose=actor.hitPose?[actor.hitPose]:[];projectWizard(g,combatCamera);}g.position.set(actor.x,0,actor.z);const p=g.userData.puppet;return [p.head,...p.parts.map(x=>x.mesh)].filter(m=>m.visible).map(m=>meshOutline(m,camera));}
function project(p){const v=new T.Vector3(p.x,p.y||0,p.z).project(combatCamera);return {x:v.x,y:v.y};}
export function areaTouches(target,point,radius,dir=null,cone=false,ring=false,height=1){if(Math.hypot(target.x-point.x,target.z-point.z)>radius+5+height)return false;const shape=actorShapes(target),angle=dir?Math.atan2(dir.z,dir.x):0,arc=cone?1.05:Math.PI,segments=32;for(let i=0;i<segments;i++){const a=angle-arc+i*2*arc/segments,b=angle-arc+(i+1)*2*arc/segments,inner=ring?Math.max(0,radius-.6):0,pts=[];for(const y of [point.y||0,(point.y||0)+height])for(const [r,t] of [[inner,a],[radius,a],[radius,b],[inner,b]])pts.push(project({x:point.x+Math.cos(t)*r,y,z:point.z+Math.sin(t)*r}));const poly=hull(pts);if(shape.some(s=>overlaps(poly,s)))return true;}return false;}
export function shotTouches(e,from,to,target){const mesh=e.mesh;if(!mesh?.geometry)return areaTouches(target,{x:to.x,y:to.y??1,z:to.z},e.radius||.25,null,false,false,.3);const origin=mesh.position.clone(),before=new T.Vector3(from.x,from.y??origin.y,from.z),next=new T.Vector3(to.x,to.y??origin.y,to.z),swept=hull([...meshOutline(mesh,combatCamera,before.sub(origin)),...meshOutline(mesh,combatCamera,next.sub(origin))]);return actorShapes(target).some(s=>overlaps(swept,s));}
export function wardTouches(target,w){const nx=w.nx??1,nz=w.nz??0,pts=[];for(const y of [0,2.4])for(const side of [-1,1])for(const depth of [-.15,.15])pts.push(project({x:w.x-nz*w.width*.5*side+nx*depth,y,z:w.z+nx*w.width*.5*side+nz*depth}));const shape=hull(pts);return actorShapes(target).some(p=>overlaps(shape,p));}

export function shotContact(e,from,to,target){if(!shotTouches(e,from,to,target))return null;let lo=0,hi=1;for(let i=0;i<8;i++){const mid=(lo+hi)/2;if(shotTouches(e,from,from.clone().lerp(to,mid),target))hi=mid;else lo=mid;}return hi;}
